public function maybe_run_version_upgrade(): void {
	if ( ! current_user_can( 'manage_options' ) ) {
		return;
	}

	$installed_version = get_option( 'wppo_version', '' );

$fs = $this->get_filesystem();
if ( ! $fs || $fs->exists( $marker_path ) ) {
	return;
}

if ( ! $this->prepare_cache_dir() ) {
	return;
}

$written = $fs->put_contents( $marker_path, (string) time(), FS_CHMOD_FILE );
if ( ! $written ) {
	return;
}
